 case 6:if(Time.time<until)return;Check(bird.CurrentHealth==13&&hitFrames.Count>=3&&State(bird)=="FleeState","actual arrow collision plus direct damage preserves flutter then flee");Object.Destroy(wall);wall=null;Ground(bird,-12);Put(player.transform,new Vector2(-40,1));until=Time.time+3;step=7;break;
